// receipt stands for the scope as it is, and no refusal was recorded on the
// scope after it. It is what reached, attention and doctor ask, instead of
// the mere presence of a receipt.
func (s Store) closedByReceipt(ref string) (bool, error) {
	receipt, err := s.ReadCloseoutReceipt(ref)
	if err != nil || receipt == nil {
		return false, err
	}
	policy, _, err := s.loadReviewPolicy()
	if err != nil {
		return false, err
	}
	if s.closeoutReceiptStands(*receipt, policy) != nil {
		return false, nil
	}
	// The applicable terminal verifier, as closeout asks it: the review, a
	// review recorded after the receipt included, the children and the gates.
	state, err := s.getCloseoutState(ref, false)
	if err != nil {
		return false, nil
	}
	return state.Terminal, nil
}

// scopeReviewRecorded reports a review of the scope on file: a bundle or a
// legacy attempt. A record that cannot be read counts as recorded, so an
// unreadable rejection never turns into an exemption.
func (s Store) scopeReviewRecorded(ref string) bool {
	bundles, err := s.ReadReviewBundles(ref)
	if err != nil || len(bundles.Bundles) > 0 || !bundles.Coverage.CompleteFor(ref) {
		return true
	}
	attempts, err := s.ReadReviewAttempts(ref)
	return err != nil || len(attempts.Attempts) > 0 || !attempts.Coverage.CompleteFor(ref)
}

// closeoutApprovalOrigin is the origin an exempt scope's approval reports.
func closeoutApprovalOrigin(decision CloseoutReviewDecision) string {
	return "not-required:" + decision.PolicyKey + "=" + decision.PolicyValue
}

func closeoutExemptionWarning(ref string, decision CloseoutReviewDecision) string {
	return "review: not-required for " + ref + " (" + decision.PolicyKey + "=" + decision.PolicyValue + ", " + decision.Reason + "); `pose close " + ref + "` is still required"
}

// CloseoutReviewOwing is an open aggregate scope that owes its own review under
// the adopted policy and holds no recorded approval yet, for `pose doctor`.
type CloseoutReviewOwing struct {
	Scope    string                 `json:"scope"`
	Decision CloseoutReviewDecision `json:"decision"`
	// Previous is the rule that applied before, when a recorded input shows
	// it; with no snapshot it says the comparison is unknown.
	Previous string `json:"previous"`
	Action   string `json:"action"`
}

// CloseoutReviewsOwed lists the open milestones and roadmaps that, under the
// adopted closeout review policy, owe a review they do not have. A legacy
// policy returns nothing. Close remains the authoritative gate.
func (s Store) CloseoutReviewsOwed() ([]CloseoutReviewOwing, error) {
	policy, _, err := s.loadReviewPolicy()
	if err != nil || !policy.CloseoutReviewAdopted() {
		return nil, err
	}
	roadmaps, err := s.ListRoadmaps()
	if err != nil {
		return nil, err
	}
	refs := []string{}
	for _, rm := range roadmaps {
		if s.closeoutScopeHistorical(ScopeRef{Kind: "roadmap", Slug: rm.Slug}) {
			continue
		}
		for _, milestone := range rm.Milestones {
			refs = append(refs, "milestone:"+rm.Slug+"/"+milestone.ID)
		}
		refs = append(refs, "roadmap:"+rm.Slug)
	}
	owing := []CloseoutReviewOwing{}
	for _, ref := range refs {
		closed, err := s.closedByReceipt(ref)
		if err != nil {
			return nil, err
		}
		if closed {
			continue
		}
		decision, err := s.currentCloseoutDecision(ref, policy)
		if err != nil {
			return nil, err
		}
		if !decision.Required {
			continue
		}
		// A recorded approval counts only while it satisfies the current
		// obligation: fresh, for the scope as it is now.
		if eval, err := s.ReviewCheck(ref); err == nil && eval.Approved && eval.Fresh {
			continue
		}
		action := "seal and review " + ref + " (`pose review bundle " + ref + " --seal`), then `pose close " + ref + "`"
		if !decision.Known {
			action = "resolve " + strings.Join(decision.Diagnostics, "; ")
		}
		owing = append(owing, CloseoutReviewOwing{Scope: ref, Decision: decision, Previous: "unknown: no snapshot of the earlier policy or composition is recorded", Action: action})
	}
	return owing, nil
}

func mustScope(ref string) ScopeRef {
	scope, _ := ParseScopeRef(ref)
	return scope
}

… tReceipt publishes a receipt where none exists. It never
// replaces one: an equal receipt is the caller's to verify, a different one
// stays as it is.
func (s Store) PublishCloseoutReceipt(receipt CloseoutReceipt) error {
	path, err := s.CloseoutReceiptPath(receipt.Scope)
	if err != nil {
		return err
	}
	if existing, err := s.ReadCloseoutReceipt(receipt.Scope); err != nil {
		return err
	} else if existing != nil {
		return ErrCloseoutReceiptExists
	}
	raw, err := json.MarshalIndent(receipt, "", "  ")
	if err != nil {
		return err
	}
	if err := s.fsys().MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	err = s.fsys().Publish(path, append(raw, '\n'), 0o644, PublishDerived, PublishExpectation{Mode: ExpectAbsent})
	if errors.Is(err, ErrPublishConflict) {
		return ErrCloseoutReceiptExists
	}
	return err
}

// A roadmap's close publishes its status and then its receipt. Between the
// two an intent stands, so a close interrupted there reads as incomplete,
// never as a roadmap closed before adoption (spec
// pose-closeout-review-policy-by-cost-benefit R4, R7).
func (s Store) closeoutIntentPath(ref string) (string, error) {
	path, err := s.CloseoutReceiptPath(ref)
	if err != nil {
		return "", err
	}
	return strings.TrimSuffix(path, ".json") + ".intent.json", nil
}

// closeoutIntentPending reports an intent on file. What cannot be read is an
// error, which the caller treats as pending: it never proves history.
func (s Store) closeoutIntentPending(ref string) (bool, error) {
	path, err := s.closeoutIntentPath(ref)
	if err != nil {
		return false, err
	}
	if _, err := s.fsys().Lstat(path); err == nil {
		return true, nil
	} else if os.IsNotExist(err) {
		return false, nil
	} else {
		return false, err
	}
}

// PublishCloseoutIntent records that this engine is closing ref under the
// adopted policy, before the roadmap's status is published.
func (s Store) PublishCloseoutIntent(ref string, decision CloseoutReviewDecision, now time.Time) error {
	path, err := s.closeoutIntentPath(ref)
	if err != nil {
		return err
	}
	raw, err := json.MarshalIndent(map[string]any{"schema_version": 1, "scope": ref, "started_at": now.UTC().Format(time.RFC3339), "review": decision.Review()}, "", "  ")
	if err != nil {
		return err
	}
	if err := s.fsys().MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return s.fsys().Publish(path, append(raw, '\n'), 0o644, PublishDerived, PublishExpectation{Mode: ExpectAny})
}

// ClearCloseoutIntent removes the intent once the receipt stands.
func (s Store) ClearCloseoutIntent(ref string) error {
	path, err := s.closeoutIntentPath(ref)
	if err != nil {
		return err
	}
	if err := s.fsys().Remove(path); err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

// roadmapCriteriaBlockers evaluates a roadmap's cut criteria from the indexed
// delivery graph, as the roadmap gate does: a criterion that does not pass,
// or a manual review that does not resolve inside the project. A graph that
// cannot be read is a blocker, never a pass.
func (s Store) roadmapCriteriaBlockers(slug string) []string {
	graph, err := s.GetDeliveryIntegrity("")
	if err != nil {
		return []string{"the cut criteria of roadmap " + slug + " cannot be evaluated: " + err.Error()}
	}
	blockers := []string{}
	for _, criterion := range graph.RoadmapCriteria {
		if criterion.Roadmap != slug {
			continue
		}
		if !criterion.Passed {
			blockers = append(blockers, criterion.ID+": "+strings.Join(criterion.Reasons, "; "))
		}
		for _, ref := range criterion.Refs {
			relative, manual := strings.CutPrefix(ref, "manual-review:")
			if !manual {
				continue
			}
			path := filepath.Join(s.Root, filepath.FromSlash(relative))
			if !filepath.IsLocal(filepath.FromSlash(relative)) || !artifactPathWithin(s.fsys(), s.Root, path) {
				blockers = append(blockers, criterion.ID+": manual review escapes project")
				continue
			}
			if info, err := s.fsys().Stat(path); err != nil || info.IsDir() {
				blockers = append(blockers, criterion.ID+": manual review does not resolve: "+relative)
			}
		}
	}
	return blockers
}

