package pose

// The capability catalog describes everything a project can adopt — what it
// changes day to day, since which version, whether a new instance gets it,
// what it requires — and how to turn it on and off (spec
// pose-capability-catalog). `pose adopt`, `pose setup`, install and the update
// review all read it, so a capability is described once and toggled the same
// way everywhere. A decision not to adopt is recorded too, in
// .pose/policy/adoption-decisions.json, so nothing decided is asked again.

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// PolicyDocs are the raw policy documents a capability writes. Raw maps keep
// every key the engine does not model; the reader validates them on Write.
type PolicyDocs struct {
	Review map[string]any
	DoR    map[string]any
	// Root is the instance the documents were loaded from, for an adoption
	// that copies a declared value (the project id) into policy.
	Root string

	reviewOriginal, dorOriginal []byte
	// reviewRead and dorRead are the bytes each document was loaded from:
	// Write publishes only over them (spec
	// pose-writer-coordination-and-atomic-publication R2).
	reviewRead, dorRead PublishExpectation
	// FS is the filesystem the documents were loaded from; a prerequisite
	// that checks an installed file reads it there.
	FS Files
}

func LoadPolicyDocsIn(files Files, root string) (PolicyDocs, error) {
	docs := PolicyDocs{Root: root, FS: files}
	reads := map[string]PublishExpectation{}
	load := func(rel string) (map[string]any, []byte, error) {
		raw, err := files.ReadFile(filepath.Join(root, ".pose", "policy", rel))
		if errors.Is(err, os.ErrNotExist) {
			reads[rel] = PublishExpectation{Mode: ExpectAbsent}
			return map[string]any{}, nil, nil
		}
		reads[rel] = ExpectBytes(raw, true)
		if err != nil {
			return nil, nil, err
		}
		doc := map[string]any{}
		if err := json.Unmarshal(raw, &doc); err != nil {
			return nil, nil, fmt.Errorf("pose: invalid .pose/policy/%s: %w", rel, err)
		}
		canonical, _ := json.Marshal(doc)
		return doc, canonical, nil
	}
	var err error
	if docs.Review, docs.reviewOriginal, err = load("review.json"); err != nil {
		return docs, err
	}
	if docs.DoR, docs.dorOriginal, err = load("dor.json"); err != nil {
		return docs, err
	}
	docs.reviewRead, docs.dorRead = reads["review.json"], reads["dor.json"]
	return docs, nil
}

// LoadPolicyDocs reads and writes the filesystem directly; LoadPolicyDocsIn takes the
// operation's files.
func LoadPolicyDocs(root string) (PolicyDocs, error) {
	return LoadPolicyDocsIn(NativeFiles(), root)
}

// Rendered returns the documents as they would be written, validated by the
// readers, and which of them changed.
func (d PolicyDocs) Rendered(store Store) (review, dor []byte, reviewChanged, dorChanged bool, err error) {
	reviewCanonical, _ := json.Marshal(d.Review)
	dorCanonical, _ := json.Marshal(d.DoR)
	reviewChanged = !bytes.Equal(reviewCanonical, d.reviewOriginal)
	dorChanged = !bytes.Equal(dorCanonical, d.dorOriginal)
	if review, err = json.MarshalIndent(d.Review, "", "  "); err != nil {
		return
	}
	review = append(review, '\n')
	if dor, err = json.MarshalIndent(d.DoR, "", "  "); err != nil {
		return
	}
	dor = append(dor, '\n')
	if reviewChanged {
		if _, err = store.ParseReviewPolicyDocument(review); err != nil {
			return
		}
	}
	if dorChanged {
		var policy DoRPolicy
		if err = json.Unmarshal(dor, &policy); err != nil {
			return
		}
		if policy.AdoptedAt != "" {
			if _, perr := time.Parse("2006-01-02", policy.AdoptedAt); perr != nil {
				err = fmt.Errorf("pose: dor.json adopted_at must be YYYY-MM-DD, got %q", policy.AdoptedAt)
				return
			}
		}
	}
	return
}

// Write persists the changed documents after the readers accept them.
func (d PolicyDocs) Write(root string, store Store) error {
	requestedRoot, err := canonicalGovernanceRoot(root)
	if err != nil {
		return err
	}
	storeRoot, err := canonicalGovernanceRoot(store.Root)

	// A rolling commit limit changes historical attribution whenever an unrelated
	// commit pushes a tagged commit out of the window. Filter in Git and scan the
	// full matching history; the output bound still fails closed for huge inputs.
	out, err := gitOutputBounded(root, 32*1024*1024, posemodel.SpecTrailerLogArgs...)
	if err != nil {
		return nil, err
	}
	specCommits := posemodel.ParseSpecTrailerLog(out)
	return specCommits, nil
}

func allCommitsWithSpecTrailersIn(files posemodel.Files, root string) (map[string][]string, error) {
	out, err := gitOutputBoundedIn(files, root, 32*1024*1024, posemodel.SpecTrailerLogArgs...)
	if err != nil {
		return nil, err
	}
	return posemodel.ParseSpecTrailerLog(out), nil
}

func commitsWithSpecTrailer(root, spec string) ([]string, error) {
	specCommits, err := allCommitsWithSpecTrailers(root)
	if err != nil {
		return nil, err
	}
	return specCommits[spec], nil
}

func commitsWithSpecTrailerIn(files posemodel.Files, root, spec string) ([]string, error) {
	specCommits, err := allCommitsWithSpecTrailersIn(files, root)
	if err != nil {
		return nil, err
	}
	return specCommits[spec], nil
}

func mergeObservedPaths(commitPathLists [][]posemodel.ObservedPath) []posemodel.ObservedPath {
	type pathState struct {
		action  string
		oldPath string
		newPath string
	}
	stateByPath := map[string]pathState{}
	for _, paths := range commitPathLists {
		for _, p := range paths {
			switch p.Action {
			case "created":
				if prev, ok := stateByPath[p.Path]; ok && prev.action == "removed" {
					stateByPath[p.Path] = pathState{action: "modified", newPath: p.Path}
				} else {
					stateByPath[p.Path] = pathState{action: "created", newPath: p.Path}
				}
			case "modified":
				if _, ok := stateByPath[p.Path]; !ok {
					stateByPath[p.Path] = pathState{action: "modified", newPath: p.Path}
				}
			case "removed":
				if prev, ok := stateByPath[p.Path]; ok && prev.action == "created" {
					delete(stateByPath, p.Path)
				} else {
					stateByPath[p.Path] = pathState{action: "removed", newPath: p.Path}
				}
			case "renamed":
				if prev, ok := stateByPath[p.OldPath]; ok && prev.action == "created" {
					delete(stateByPath, p.OldPath)
					stateByPath[p.NewPath] = pathState{action: "created", newPath: p.NewPath}
				} else {
					initialOld := p.OldPath
					if prev, ok := stateByPath[p.OldPath]; ok && prev.action == "renamed" {
						initialOld = prev.oldPath
						delete(stateByPath, p.OldPath)
					}
					stateByPath[p.NewPath] = pathState{action: "renamed", oldPath: initialOld, newPath: p.NewPath}
				}
			}
		}
	}
	result := make([]posemodel.ObservedPath, 0, len(stateByPath))
	for path, st := range stateByPath {
		switch st.action {
		case "created":
			result = append(result, posemodel.ObservedPath{Action: "created", Path: path})
		case "modified":
			result = append(result, posemodel.ObservedPath{Action: "modified", Path: path})
		case "removed":
			result = append(result, posemodel.ObservedPath{Action: "removed", Path: path})
		case "renamed":
			result = append(result, posemodel.ObservedPath{Action: "renamed", OldPath: st.oldPath, NewPath: st.newPath})
		}
	}
	sort.Slice(result, func(i, j int) bool { return observedSortKey(result[i]) < observedSortKey(result[j]) })
	return result
}

