   155				diagnostics = append(diagnostics, "ADR "+name+" could not be read: "+err.Error())
   156				continue
   157			}
   158			fm, adrBody := SplitFrontmatter(string(raw))
   159			if declared, ok := fm["roadmaps"]; ok {
   160				value := strings.TrimSpace(declared)
   161				if !strings.HasPrefix(value, "[") || !strings.HasSuffix(value, "]") {
   162					diagnostics = append(diagnostics, "ADR "+name+" declares roadmaps: outside a [list]")
   163				} else {
   164					for _, item := range parseInlineList(value) {
   165						ref, err := ParseArtifactRef(item)
   166						if err != nil || ref.Kind != "roadmap" || ref.Milestone != "" {
   167							diagnostics = append(diagnostics, fmt.Sprintf("ADR %s declares %q, not roadmap:<slug>", name, item))
   168							continue
   169						}
   170						if ref.Project != "" && ref.Project != project {
   171							continue // a roadmap of another project: not this association
   172						}
   173						if _, err := s.GetRoadmap(ref.Slug); err != nil {
   174							diagnostics = append(diagnostics, fmt.Sprintf("ADR %s declares %s, which names no roadmap of this project", name, item))
   175							continue
   176						}
   177						if ref.Slug == rm.Slug {
   178							found[name] = true
   179						}
   180					}
   181				}
   182			}
   183			for _, dest := range markdownLinkDestinations(adrBody) {
   184				target := filepath.Clean(filepath.Join(s.adrDir(), filepath.FromSlash(dest)))
   185				if filepath.Dir(target) != filepath.Clean(s.roadmapsDir()) || !strings.HasSuffix(target, ".md") {
   186					continue
   187				}
   188				// A link into the roadmaps namespace is an association input: one
   189				// that does not resolve to a roadmap leaves the answer unknown.
   190				if info, err := s.fsys().Lstat(target); err != nil || !info.Mode().IsRegular() || !artifactPathWithin(s.fsys(), s.Root, target) {
   191					diagnostics = append(diagnostics, "ADR "+name+" links to "+dest+", which is not a roadmap of this project")
   192					continue
   193				}
   194				if target == roadmapPath {
   195					found[name] = true
   196				}
   197			}
   198		}
   199		adrs := make([]string, 0, len(found))
   200		for name := range found {
   201			adrs = append(adrs, name)
   202		}
   203		sort.Strings(adrs)
   204		sort.Strings(diagnostics)
   205		return adrs, diagnostics
   206	}

			}
			assurance := s.DescribeReviewAssurance(bundle, att)
			eval.Assurance = &assurance
			return
		}
	}
	if !eval.Required && eval.Current == nil {
		return
	}
	independence, required := "", ""
	if scope, err := ParseScopeRef(eval.Scope); err == nil {
		if policy, policyErr := s.GetReviewPolicy(); policyErr == nil {
			independence = policy.ReviewerIndependence[scope.Kind]
			required = policy.ReviewIdentityAssurance(scope.Kind)
		}
	}
	assurance := describeAttemptAssurance(required, independence, eval.Current)
	eval.Assurance = &assurance
}

