func (s Store) ScopeDigest(ref string) (string, error) {
	scope, err := ParseScopeRef(ref)
	if err != nil {
		return "", err
	}
	policy, policyRaw, err := s.loadReviewPolicy()
	if err != nil {
		return "", err
	}
	profileRef := policy.Profiles[scope.Kind]
	var profileRaw []byte
	if profileRef != "" {
		_, profileRaw, err = s.loadReviewProfile(profileRef)
		// An absent profile contributes empty bytes, which is itself a distinct
		// digest input. Refusing to compute the digest would make a diff that
		// removes the profile impossible to review — the profile governing the
		// review would be the one the review is about. A profile that exists but
		// is malformed is still a hard error.
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return "", err
		}
	}
	base := map[string]any{"schema_version": ReviewSchemaVersion, "scope": ref, "policy": string(policyRaw), "profile": string(profileRaw)}
	switch scope.Kind {
	case "spec":
		sp, err := s.GetSpec(scope.Slug)
		if err != nil {
			return "", err
		}
		base["content"] = strings.ReplaceAll(strings.TrimSpace(sp.Body), "\r\n", "\n")
		base["depends_on"] = sp.DependsOn
		if len(sp.Remediates) > 0 {
			if err := s.ValidateRemediationLineage(*sp); err != nil {
				return "", err
			}
			links := append([]string{}, sp.Remediates...)
			sort.Strings(links)
			base["remediates"] = links
		}
		base["components"] = sp.Components
	case "milestone":
		rm, err := s.GetRoadmap(scope.Roadmap)
		if err != nil {
			return "", err
		}
		var target *Milestone
		for i := range rm.Milestones {
			if rm.Milestones[i].ID == scope.Milestone {
				target = &rm.Milestones[i]
				break
			}
		}
		if target == nil {
			return "", fmt.Errorf("pose: milestone %s/%s not found", scope.Roadmap, scope.Milestone)
		}
		children := map[string]string{}
		for _, raw := range target.Specs {
			slug, external := s.milestoneMember(raw)
			if external {
				// Another project's member is sealed by the federated
				// manifest; its identity is what this scope depends on.
				children[raw] = "external"
				continue
			}
			d, err := s.ScopeDigest("spec:" + slug)
			if err != nil {
				return "", err
			}
			children[slug] = d
		}
		base["milestone"] = target
		base["section"] = roadmapMilestoneSection(rm.Body, target.ID)
		base["children"] = children
	case "roadmap":
		rm, err := s.GetRoadmap(scope.Slug)
		if err != nil {
			return "", err
		}
		children := map[string]string{}
		for _, milestone := range rm.Milestones {
			d, err := s.ScopeDigest("milestone:" + rm.Slug + "/" + milestone.ID)
			if err != nil {
				return "", err
			}
			children[milestone.ID] = d
		}
		base["content"] = strings.ReplaceAll(strings.TrimSpace(rm.Body), "\r\n", "\n")
		base["children"] = children
		if rm.UnreviewedMilestones != "" {
			base["unreviewed_milestones"] = rm.UnreviewedMilestones

		return true // sibling checkouts have no consumer gitlink to compare.
	}
	parentTop, err := captureFederatedGit(files, parent.Root, "rev-parse", "--show-toplevel")
	if err != nil {
		markFederatedGitReadUnknown(files, parent.Root, "federated parent Git root could not be identified")
		return true
	}
	if !sameProjectRoot(files, parent.Root, strings.TrimSpace(string(parentTop))) {
		return true
	}
	parentReal, err1 := files.EvalSymlinks(parent.Root)
	childReal, err2 := files.EvalSymlinks(child.Root)
	if err1 != nil || err2 != nil {
		return false
	}
	rel, err := filepath.Rel(parentReal, childReal)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return true // sibling project, explicitly selected in Roots.
	}
	listing, err := captureFederatedGit(files, parent.Root, "ls-tree", "HEAD", "--", filepath.ToSlash(rel))
	if err != nil {
		return false
	}
	fields := strings.Fields(string(listing))
	if len(fields) < 3 || fields[0] != "160000" || fields[1] != "commit" {
		return false
	}
	return fields[2] == revision
}

// federatedGitlinkMatches reads the filesystem directly; federatedGitlinkMatchesIn reads the operation's files.
func federatedGitlinkMatches(parent, child Store, revision string) bool {
	return federatedGitlinkMatchesIn(NativeFiles(), parent, child, revision)
}

func federatedSourceProof(files Files, source Store, identity ArtifactRef, pinnedRevision string) (string, string, string, string, []string, []FederatedDependencyEvidence, []string) {
	scope := localFederatedScope(identity)
	state, err := source.GetCloseoutState(scope)
	if err != nil || !state.Terminal {
		return "", "", "", "", nil, nil, []string{scope + ":source-closeout-not-terminal"}
	}
	// A milestone or roadmap the source closed without its own review, under
	// its adopted closeout review policy, is proven by the receipt of that
	// close: the source's policy decides, never the consumer's. Its members
	// are federated with their own reviews (spec
	// pose-closeout-review-policy-by-cost-benefit).
	if receipt := state.CloseoutReceipt; receipt != nil && !receipt.Decision.Required && (identity.Kind == "milestone" || identity.Kind == "roadmap") {

		// there; say where it went, or the pass reads as magic (spec
		// pose-release-archival-attested-by-the-ledger).
		for _, a := range graph.Archivals {
			fmt.Fprintf(stdout, "artifact.archived=%s -> %s (release %s)\n", a.Pending, a.Archived, a.Version)
		}
		for _, finding := range graph.Findings {
			render(stdout, stderr).Finding(cliout.Finding{
				State: cliout.StateFromKey(finding.Severity), Code: finding.Code, Path: finding.Path,
				Message: finding.Message, Remediation: finding.Remediation,
			})
		}
	}
	if strict {
		for _, finding := range graph.Findings {
			if finding.Severity == "error" || finding.Severity == "critical" {
				if !jsonOutput {
					PrintContributorFailureHint(root, stderr, cliLocaleValue())
				}
				return 1
			}
		}
	}
	if deliveryGraph, err := buildCurrentDeliveryGraph(root); err == nil {
		if raw, err := deliveryGraph.IndexJSON(); err == nil {
			refreshDeliveryIndex(root, append(raw, '\n'), stderr)
		}
	}
	return 0
}

